import {emptyData,validateData,uid,esc,safeURL,remaining,progress,priority,suggestedStart,estimateHours,dayKey,localInput,zonedISO,planStudy,importCSV,importICS,exportICS,GitHubStore} from './core.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='module-planner:v1', CONFIG='module-planner:github';let data=emptyData(),gh=null,busy=false,imported=null,importWarnings=[],undo=null,view='assignments';let startupError='';
try{const raw=localStorage.getItem(KEY);if(raw)data=validateData(JSON.parse(raw));}catch{startupError='The saved data could not be read. Export the recovery copy in Settings before replacing it.';}
let ghConfig={repo:'',path:'module-planner/assignments.json',branch:'main'};try{ghConfig={...ghConfig,...JSON.parse(localStorage.getItem(CONFIG)||'{}')};}catch{}
let timer;function toast(message,action){clearTimeout(timer);const el=$('#toast');el.replaceChildren(document.createTextNode(message));if(action){const b=document.createElement('button');b.textContent=action.label;b.onclick=action.run;el.append(b);}el.hidden=false;timer=setTimeout(()=>el.hidden=true,action?15000:6500);}
function save(next=data){const clean=validateData(next);try{if(startupError)throw Error(startupError);localStorage.setItem(KEY,JSON.stringify(clean));}catch(e){throw Error('Could not save on this device. '+(e.message||'Storage may be full. Export a backup.'));}data=clean;render();}
function mutate(fn){try{const next=structuredClone(data);fn(next);save(next);return true;}catch(e){toast(e.message);return false;}}
function touch(t){t.updatedAt=new Date().toISOString();}
function formatDate(iso,zone=data.settings.zone){return iso?new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:zone}).format(new Date(iso)): 'No deadline set';}
function formatDay(key){return new Date(key+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});}
const hours=h=>Number(h.toFixed(2))+'h';
function showView(next){if(!['assignments','plan','modules','settings'].includes(next))next='assignments';view=next;$$('.view').forEach(e=>e.hidden=e.id!==view);$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.view===view));$('#page-title').textContent=({assignments:'Your assignments',plan:'Make room for progress',modules:'Your modules',settings:'Storage & settings'})[view];$('#page-subtitle').textContent=({assignments:'A little structure. A clearer week.',plan:'A realistic plan, based on the hours you have.',modules:'Every module. One place to keep track.',settings:'Keep your work backed up and your plan realistic.'})[view];if(location.hash.slice(1)!==next)history.replaceState(null,'','#'+next);render();}
function stats(){const active=data.tasks.filter(t=>t.status!=='completed');const overdue=active.filter(t=>t.due&&Date.parse(t.due)<Date.now());const week=active.filter(t=>t.due&&Date.parse(t.due)>=Date.now()&&Date.parse(t.due)<Date.now()+7*86400000);const done=data.tasks.length-active.length;$('#stats').innerHTML=[['Active assignments',active.length,'Across '+new Set(active.map(t=>t.module)).size+' modules'],['Due in 7 days',week.length,overdue.length?overdue.length+' overdue':'Keep the week in view'],['Work remaining',hours(active.reduce((n,t)=>n+remaining(t),0)),'Estimated, minus logged time'],['Completed',done,data.tasks.length?Math.round(done/data.tasks.length*100)+'% of assignments':'Your progress starts here']].map(([label,note,detail])=>`<div class="stat"><span class="stat-label">${label}</span><strong>${esc(note)}</strong><small>${esc(detail)}</small></div>`).join('');}
function modules(){return [...new Set(data.tasks.map(t=>t.module))].sort((a,b)=>a.localeCompare(b));}
function taskHTML(t){const p=priority(t,data.settings);const late=t.due&&Date.parse(t.due)<Date.now()&&t.status!=='completed';const start=suggestedStart(t,data.settings);const logged=t.logs.reduce((a,l)=>a+l.hours,0);return `<article class="task ${t.status==='completed'?'completed-task':''}" data-id="${esc(t.id)}"><div class="task-top"><input type="checkbox" data-action="complete" ${t.status==='completed'?'checked':''} aria-label="Mark ${esc(t.title)} completed"><div class="task-main"><div class="module-label">${esc(t.module)}</div><h3>${esc(t.title)}</h3><div class="task-meta"><span class="badge ${t.status==='completed'?'completed':p}">${t.status==='completed'?'Completed':p[0].toUpperCase()+p.slice(1)+' priority'}</span><span class="${late?'overdue':''}">${late?'Overdue · ':''}${esc(formatDate(t.due,t.zone))}${t.due?' · '+esc(t.zone):''}</span><span>· ${hours(remaining(t))} remaining</span>${t.weight!==''?'<span>· '+t.weight+'% weighting</span>':''}</div></div></div><div class="task-foot"><div class="progress-area">${progress(t)}% progress <progress value="${progress(t)}" max="100" aria-label="Assignment progress"></progress></div><div class="actions"><button data-action="log">Log time</button><button data-action="edit">Edit</button><button data-action="duplicate" aria-label="Duplicate ${esc(t.title)}">Duplicate</button><button data-action="delete" aria-label="Delete ${esc(t.title)}">Delete</button></div></div><details class="details"><summary>Checklist & details${t.steps.length?' · '+t.steps.filter(s=>s.done).length+'/'+t.steps.length+' steps':''}</summary><p class="muted">Estimated total: ${hours(t.estimate)} · Logged: ${hours(logged)}${start?' · Suggested start: '+formatDay(start):''}</p>${start&&start<dayKey(new Date(),data.settings.zone)&&t.status!=='completed'?'<p class="overdue">Start as soon as possible; the suggested start date has passed.</p>':''}${t.steps.map((s,i)=>`<label class="check-step"><input type="checkbox" data-action="step" data-index="${i}" ${s.done?'checked':''}><span>${esc(s.text)}</span></label>`).join('')}${!t.steps.length?'<p class="muted">No checklist steps yet. Add them using Edit.</p>':''}${t.notes?'<p class="notes">'+esc(t.notes)+'</p>':''}${safeURL(t.source)?'<p><a target="_blank" rel="noopener noreferrer" href="'+esc(safeURL(t.source))+'">Open assessment brief ↗</a></p>':''}${t.logs.length?'<p class="muted">Study log</p>'+t.logs.map(l=>`<div class="check-step"><span>${esc(formatDate(l.at))} · ${hours(l.hours)}</span><button data-action="remove-log" data-log="${esc(l.id)}">Remove</button></div>`).join(''):''}<small class="muted">Effort and start dates are planning estimates. Check Moodle for official deadlines and extensions.</small></details></article>`;}
function renderAssignments(){const selected=$('#module-filter').value;$('#module-filter').innerHTML='<option value="">All modules</option>'+modules().map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('');$('#module-filter').value=modules().includes(selected)?selected:'';const q=$('#search').value.toLowerCase(),status=$('#status-filter').value;let tasks=data.tasks.filter(t=>(!selected||t.module===selected)&&[t.title,t.module,t.notes].some(s=>s.toLowerCase().includes(q))).filter(t=>status==='all'||status==='active'&&t.status!=='completed'||status===t.status||status==='overdue'&&t.status!=='completed'&&t.due&&Date.parse(t.due)<Date.now()||status==='week'&&t.status!=='completed'&&t.due&&Date.parse(t.due)>=Date.now()&&Date.parse(t.due)<=Date.now()+7*86400000);const mode=$('#sort').value;tasks.sort((a,b)=>mode==='effort'?remaining(b)-remaining(a):mode==='priority'?({high:0,medium:1,low:2}[priority(a,data.settings)]-{high:0,medium:1,low:2}[priority(b,data.settings)]||((Date.parse(a.due)||Infinity)-(Date.parse(b.due)||Infinity))):((Date.parse(a.due)||Infinity)-(Date.parse(b.due)||Infinity)));$('#result-count').textContent=tasks.length+' assignment'+(tasks.length===1?'':'s');$('#task-list').innerHTML=tasks.length?tasks.map(taskHTML).join(''):`<div class="empty"><div class="empty-icon">▤</div><h2>${data.tasks.length?'Nothing matches these filters':'A clear desk. A fresh start.'}</h2><p>${data.tasks.length?'Try another search or choose All assignments.':'Add your first assignment or import a calendar / backup. Your real deadlines and study plan will appear here.'}</p><button class="primary" data-action="new">＋ Add assignment</button> <button data-action="open-import">Import assignments</button></div>`;}
function renderPlan(){const plan=planStudy(data);$('#plan').innerHTML=`<div class="panel"><div class="section-line"><h2>The next 14 days</h2><button data-view="settings">Adjust study hours</button></div><p class="muted">${hours(data.settings.dailyHours)} per study day · ${data.settings.weekends?'Weekends included':'Weekdays only'} · ${esc(data.settings.zone)}. Work is allocated by earliest deadline. Today uses your full daily allowance; adjust it if you have less time left. No work is counted as safely finished on the deadline day.</p>${plan.warnings.length?'<div class="plan-warnings">'+plan.warnings.map(esc).join('<br>')+'</div>':''}${!data.tasks.some(t=>t.status!=='completed')?'<p>Add active assignments to generate your plan.</p>':plan.days.map(d=>`<div class="plan-day"><strong>${formatDay(d.date)}${d.date===dayKey(new Date(),data.settings.zone)?'<br><small>Today</small>':''}</strong><div>${d.blocks.map(b=>`<div class="plan-block"><span>${esc(b.task.title)}<small>${esc(b.task.module)}${b.late?' · Deadline day or overdue — review timing':''}</small></span><b>${hours(b.hours)}</b></div>`).join('')||'<span class="muted">'+(d.capacity?'Room to breathe. No work allocated.':'Rest day')+'</span>'}</div></div>`).join('')}${plan.unallocated.length?'<div class="plan-warnings"><b>Beyond this 14-day plan</b><br>'+plan.unallocated.map(x=>esc(x.task.title)+' · '+hours(x.hours)+' remaining').join('<br>')+'</div>':''}</div>`;}
function renderModules(){$('#modules').innerHTML=modules().length?'<div class="module-grid">'+modules().map(m=>{const ts=data.tasks.filter(t=>t.module===m),active=ts.filter(t=>t.status!=='completed');return `<div class="panel"><div class="module-label">MODULE</div><h2>${esc(m)}</h2><p>${active.length} active · ${ts.length-active.length} completed<br>${hours(active.reduce((a,t)=>a+remaining(t),0))} estimated work remaining</p><div class="actions"><button data-action="filter-module" data-module="${esc(m)}">View assignments</button><button data-action="add-module-task" data-module="${esc(m)}">＋ Assignment</button></div></div>`;}).join('')+'</div>':'<div class="empty"><h2>Your modules will appear here</h2><p>Add an assignment with a module name to start grouping your coursework.</p><button data-action="new" class="primary">Add assignment</button></div>';}
function renderSettings(){if($('#github-token')&&document.activeElement?.closest('#settings'))return;$('#settings').innerHTML=`<div class="settings-grid"><section class="panel"><h2>Study capacity</h2><p class="muted">Used for your study plan and suggested start dates. Estimates are editable, and logged time reduces the hours remaining.</p><form id="capacity-form"><label>Study hours per day<input name="dailyHours" type="number" value="${data.settings.dailyHours}" min="0.25" max="16" step="0.25" required></label><label>Buffer before deadline (study days)<input name="bufferDays" type="number" min="0" max="14" step="1" value="${data.settings.bufferDays}" required></label><label>Planning time zone<input name="zone" value="${esc(data.settings.zone)}" required></label><label class="check-step" style="display:flex"><input type="checkbox" name="weekends" ${data.settings.weekends?'checked':''}> Include weekends</label><button class="primary">Save study settings</button></form></section><section class="panel"><h2>GitHub storage</h2><p class="muted">Save a versioned JSON file in your own repository. Connect on each device, then Pull & merge and Save to GitHub. The token stays in memory until you close or reload this page; it is never saved in a backup or sent to the app host.</p><form id="github-form"><label>Repository (owner/name)<input id="github-repo" value="${esc(ghConfig.repo)}" placeholder="Singhkingh123/my-private-planner" required></label><label>Branch<input id="github-branch" value="${esc(ghConfig.branch)}" required></label><label>JSON file path<input id="github-path" value="${esc(ghConfig.path)}" required></label><label>Fine-grained GitHub access token<input id="github-token" type="password" autocomplete="off" spellcheck="false" placeholder="Enter here, never in chat" ${gh?'':'required'}></label><label class="check-step" style="display:flex"><input type="checkbox" id="allow-public"> Allow assignment data in a public repository</label><div class="actions"><button class="primary" ${busy?'disabled':''}>${gh?'Reconnect':'Connect & pull'}</button><button type="button" id="disconnect" ${gh?'':'disabled'}>Disconnect</button></div></form><p id="sync-status" class="muted">${gh?'Connected for this tab. Sync is manual.':'Not connected. Local saving is active.'}</p><div class="actions"><button id="pull" ${gh?'':'disabled'}>Pull & merge</button><button id="push" ${gh?'':'disabled'}>Save to GitHub</button></div><details class="details" style="margin-left:0"><summary>Exact GitHub setup steps</summary><ol><li>On GitHub, click <b>＋ → New repository</b>. Name it <b>my-private-planner</b>, select <b>Private</b>, tick <b>Add a README file</b>, then Create repository.</li><li>Click your profile picture → <b>Settings → Developer settings → Personal access tokens → Fine-grained tokens → Generate new token</b>.</li><li>Choose an expiry, select <b>Only select repositories</b>, then your planner repository. Under <b>Repository permissions → Contents</b>, select <b>Read and write</b>. Generate and copy the token.</li><li>Enter <b>Singhkingh123/my-private-planner</b> above and paste the token into the password field. Click <b>Connect & pull</b>, then <b>Save to GitHub</b>.</li><li>On your phone, open this app and repeat the connection using the same repository and branch. Pull before editing and before saving to avoid conflicts.</li></ol><p>GitHub history retains older commits. Use a private repository for coursework details. No token is needed for local-only use.</p></details></section><section class="panel"><h2>Import & backups</h2><p class="muted">JSON preserves everything. CSV works with spreadsheets. Calendar import can bring in Moodle events; review titles, modules and submission times afterward.</p><div class="actions"><button data-action="open-import">Import JSON / CSV / ICS</button><button id="backup">Export JSON backup</button><button id="csv">Export CSV</button><button id="csv-template">CSV template</button><button id="calendar">Export deadline calendar</button></div><details class="details" style="margin-left:0"><summary>Import from Moodle</summary><ol><li>Open Moodle → <b>Dashboard → Calendar</b> (or use Calendar in the navigation).</li><li>Choose <b>Export calendar</b>, select course events and the widest available date range, then <b>Export</b> to download an .ics file. Menu names may vary.</li><li>Click <b>Import JSON / CSV / ICS</b> above, select the file, review the events, then import.</li><li>Open each imported assignment and confirm the module, official deadline and estimated hours. A calendar may omit assessments without calendar events.</li></ol></details><p class="muted">Calendar exports contain active deadlines and a one-day reminder. Notifications are handled by your calendar app. This app does not send background push notifications.</p></section><section class="panel"><h2>Device & recovery</h2><p class="muted">Assignments save automatically in this browser. Once loaded, the app can work offline when browser and hosting policies allow caching. GitHub sync needs internet.</p><p class="muted">For quick access, use your browser’s <b>Install app</b> or <b>Add to Home Screen</b> option when available.</p><div class="actions"><button id="print">Print checklist</button><button id="recovery">Export raw device data</button></div>${startupError?'<p class="error">'+esc(startupError)+'</p><button id="reset-corrupt">Backed up — reset unreadable local data</button>':''}<p id="device-status" class="muted">${navigator.onLine?'Online':'Offline'} · All displayed effort estimates are approximate.</p></section></div>`;}
function render(){const open=new Set($$('article details[open]').map(e=>e.closest('article').dataset.id));$('#today').textContent=new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:data.settings.zone}).format(new Date());stats();$('#connection').textContent=gh?'GitHub connected · manual sync':'Saved on this device';$('#moodle-note').hidden=data.tasks.length>0;renderAssignments();open.forEach(id=>{const article=$$('article').find(x=>x.dataset.id===id);if(article)article.querySelector('details').open=true;});if(view==='plan')renderPlan();if(view==='modules')renderModules();if(view==='settings')renderSettings();}
function openEditor(task=null,module=''){const f=$('#task-form');f.reset();$('#form-error').textContent='';$('#estimate-hint').textContent='Rough planning estimate; adjust for your brief and experience.';$('#editor-title').textContent=task?'Edit assignment':'Add assignment';$('#module-options').innerHTML=modules().map(m=>`<option value="${esc(m)}">`).join('');const values=task||{id:'',title:'',module,zone:data.settings.zone,type:'essay',estimate:10,difficulty:1,priority:'auto',status:'not-started',weight:'',words:'',source:'',notes:''};for(const key of ['id','title','module','zone','type','estimate','difficulty','priority','status','weight','words','source','notes'])f.elements[key].value=values[key]??'';f.elements.dueLocal.value=task?localInput(task.due,task.zone):'';f.elements.steps.value=task?task.steps.map(s=>s.text).join('\n'):'';$('#editor').showModal();}
$('#task-form').onsubmit=e=>{e.preventDefault();const f=e.target,old=data.tasks.find(t=>t.id===f.elements.id.value);try{const values=Object.fromEntries(new FormData(f));if(values.source&&!safeURL(values.source))throw Error('Use an http or https URL for the brief.');const lines=values.steps.split('\n').map(s=>s.trim()).filter(Boolean);const existing=[...(old?.steps||[])];const t={...old,...values,id:old?.id||uid(),due:values.dueLocal?zonedISO(values.dueLocal,values.zone):'',estimate:Number(values.estimate),words:Number(values.words)||0,difficulty:Number(values.difficulty),weight:values.weight===''?'':Number(values.weight),steps:lines.map(text=>{const i=existing.findIndex(s=>s.text===text);return i>=0?existing.splice(i,1)[0]:{id:uid(),text,done:false};}),logs:old?.logs||[],updatedAt:new Date().toISOString()};delete t.dueLocal;const next=structuredClone(data);next.tasks=old?next.tasks.map(x=>x.id===old.id?t:x):[...next.tasks,t];save(next);$('#editor').close();toast(old?'Assignment updated.':'Assignment added.');}catch(err){$('#form-error').textContent=err.message;}};
$('#estimate-btn').onclick=()=>{const f=$('#task-form');const r=estimateHours(f.elements.type.value,Number(f.elements.words.value),Number(f.elements.difficulty.value));f.elements.estimate.value=r.hours;$('#estimate-hint').textContent=`Suggested ${r.hours}h; rough range ${r.low}–${r.high}h. Includes planning and review. Adjust to your brief.`;};
$('#add').onclick=()=>openEditor();
for(const id of ['search','module-filter','status-filter','sort'])$('#'+id).addEventListener(id==='search'?'input':'change',renderAssignments);
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.view){showView(btn.dataset.view);return;}if(btn.dataset.close){$('#'+btn.dataset.close).close();return;}const action=btn.dataset.action;if(!action)return;if(action==='new')return openEditor();if(action==='open-import')return openImport();if(action==='filter-module'){$('#module-filter').value=btn.dataset.module;$('#status-filter').value='all';return showView('assignments');}if(action==='add-module-task')return openEditor(null,btn.dataset.module);const id=btn.closest('article')?.dataset.id,t=data.tasks.find(t=>t.id===id);if(!t)return;if(action==='edit')return openEditor(t);if(action==='duplicate'){mutate(d=>{d.tasks.push({...structuredClone(t),id:uid(),title:(t.title+' (copy)').slice(0,200),status:'not-started',logs:[],steps:t.steps.map(s=>({...s,id:uid(),done:false})),updatedAt:new Date().toISOString()});});return;}if(action==='delete'){if(!confirm(`Delete “${t.title}”? You can undo this immediately afterward.`))return;undo=structuredClone(t);if(mutate(d=>{d.tasks=d.tasks.filter(x=>x.id!==id);d.deleted[id]=new Date().toISOString();}))toast('Assignment deleted.',{label:'Undo',run:()=>{const value=undo;if(value&&mutate(d=>{delete d.deleted[value.id];d.tasks.push(value);})){$('#toast').hidden=true;undo=null;}}});return;}if(action==='log'){const value=prompt('Hours studied on this assignment (e.g. 1.5):','1');if(value===null)return;const n=Number(value);if(!Number.isFinite(n)||n<=0||n>10000)return toast('Enter a number of hours greater than zero, up to 10,000.');mutate(d=>{const x=d.tasks.find(x=>x.id===id);x.logs.push({id:uid(),hours:n,at:new Date().toISOString()});if(x.status==='not-started')x.status='in-progress';touch(x);});return;}if(action==='remove-log')mutate(d=>{const x=d.tasks.find(x=>x.id===id);x.logs=x.logs.filter(l=>l.id!==btn.dataset.log);touch(x);});});
$('#task-list').addEventListener('change',e=>{const el=e.target,id=el.closest('article')?.dataset.id;if(!id)return;mutate(d=>{const t=d.tasks.find(t=>t.id===id);if(el.dataset.action==='complete')t.status=el.checked?'completed':t.logs.length||t.steps.some(s=>s.done)?'in-progress':'not-started';if(el.dataset.action==='step'){t.steps[Number(el.dataset.index)].done=el.checked;if(t.status==='not-started'&&el.checked)t.status='in-progress';}touch(t);});});
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download('module-planner-'+dayKey()+'.json',JSON.stringify(data,null,2));}
function csvCell(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
async function syncAction(fn){if(busy)return;busy=true;$$('#github-form button,#pull,#push').forEach(b=>b.disabled=true);try{await fn();}catch(e){$('#sync-status').textContent=e.message;$('#sync-status').classList.add('error');toast(e.message);}finally{busy=false;$$('#github-form button').forEach(b=>b.disabled=false);$('#disconnect').disabled=!gh;$('#pull').disabled=!gh;$('#push').disabled=!gh;}}
document.addEventListener('submit',e=>{if(e.target.id==='capacity-form'){e.preventDefault();const f=e.target;try{new Intl.DateTimeFormat('en',{timeZone:f.elements.zone.value}).format();if(mutate(d=>d.settings={dailyHours:Number(f.elements.dailyHours.value),bufferDays:Number(f.elements.bufferDays.value),weekends:f.elements.weekends.checked,zone:f.elements.zone.value}))toast('Study settings saved.');}catch{toast('Enter a valid IANA time zone, e.g. Europe/London.');}}if(e.target.id==='github-form'){e.preventDefault();syncAction(async()=>{const token=$('#github-token').value.trim();if(!token)throw Error('Re-enter your GitHub token to reconnect.');const config={repo:$('#github-repo').value.trim(),branch:$('#github-branch').value.trim(),path:$('#github-path').value.trim()};const candidate=new GitHubStore({...config,token});const info=await candidate.inspect();if(!info.private&&!$('#allow-public').checked)throw Error('This repository is public. Choose a private repository, or explicitly tick the public data checkbox.');const next=await candidate.pull(structuredClone(data));save(next);gh=candidate;ghConfig=config;localStorage.setItem(CONFIG,JSON.stringify(config));$('#github-token').value='';$('#sync-status').textContent='Connected. Remote data merged locally. Click Save to GitHub to upload local changes.';$('#sync-status').classList.remove('error');$('#connection').textContent='GitHub connected · manual sync';});}});
document.addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(!id)return;if(id==='backup')backup();if(id==='calendar')download('assignment-deadlines.ics',exportICS(data.tasks),'text/calendar');if(id==='csv'){const headers=['title','module','due','zone','type','estimate','notes'];download('assignments.csv',[headers.join(','),...data.tasks.map(t=>headers.map(h=>csvCell(t[h])).join(','))].join('\r\n'),'text/csv');}if(id==='csv-template')download('assignment-template.csv','title,module,due,zone,type,estimate,notes\r\n','text/csv');if(id==='recovery')download('module-planner-raw-recovery.txt',localStorage.getItem(KEY)||'No saved data','text/plain');if(id==='reset-corrupt'&&confirm('Only continue if you exported the raw recovery copy. Reset unreadable local data?')){startupError='';save(emptyData());}if(id==='print')window.print();if(id==='disconnect'){gh=null;$('#github-token').value='';$('#sync-status').textContent='Disconnected. Your data remains on this device and in GitHub.';$('#disconnect').disabled=true;$('#pull').disabled=true;$('#push').disabled=true;$('#connection').textContent='Saved on this device';}if(id==='pull'&&gh)syncAction(async()=>{const next=await gh.pull(structuredClone(data));save(next);$('#sync-status').classList.remove('error');$('#sync-status').textContent='Pulled and merged. Local-only changes still need Save to GitHub.';toast('GitHub data merged.');});if(id==='push'&&gh)syncAction(async()=>{const snapshot=structuredClone(data);await gh.push(snapshot);$('#sync-status').classList.remove('error');$('#sync-status').textContent='Saved to GitHub at '+new Date().toLocaleTimeString()+'.'+(JSON.stringify(snapshot)!==JSON.stringify(data)?' New local edits need another save.':'');toast('GitHub confirmed your save.');});});
function openImport(){imported=null;importWarnings=[];$('#import-form').reset();$('#import-preview').replaceChildren();$('#import-error').textContent='';$('#import-confirm').disabled=true;$('#importer').showModal();}
$('#import-file').onchange=async()=>{const file=$('#import-file').files[0];if(!file)return;$('#import-confirm').disabled=true;$('#import-error').textContent='';$('#import-preview').replaceChildren();try{if(file.size>5*1024*1024)throw Error('Choose a file smaller than 5 MB.');const text=await file.text();importWarnings=[];if(file.name.toLowerCase().endsWith('.json')){imported=validateData(JSON.parse(text)).tasks;importWarnings.push('Imports assignments only; existing study settings and deletions are retained.');}else if(file.name.toLowerCase().endsWith('.csv'))imported=importCSV(text);else if(file.name.toLowerCase().endsWith('.ics')){const result=importICS(text);imported=result.tasks;importWarnings=result.warnings;}else throw Error('Choose a .json, .csv or .ics file.');if(!imported.length)throw Error('The file has no assignments.');$('#import-preview').innerHTML='<p>'+imported.length+' items found. Untick anything you don’t want.</p>'+importWarnings.map(w=>'<p class="error">'+esc(w)+'</p>').join('')+imported.map((t,i)=>`<label><input type="checkbox" checked data-import="${i}"><span>${esc(t.title)}<br><small>${esc(t.module)} · ${esc(formatDate(t.due,t.zone))}</small></span></label>`).join('');$('#import-confirm').disabled=false;}catch(e){imported=null;$('#import-error').textContent=e.message;}};
$('#import-form').onsubmit=e=>{e.preventDefault();if(!imported)return;const selected=$$('[data-import]:checked').map(el=>imported[Number(el.dataset.import)]);if(!selected.length){$('#import-error').textContent='Choose at least one item.';return;}try{const next=structuredClone(data);let count=0;for(const item of selected){let match=next.tasks.find(t=>t.id===item.id||item.importKey&&t.importKey===item.importKey);if(next.deleted[item.id])continue;if(match){if(!confirm(`“${match.title}” already exists. Replace its details with this imported version?`))continue;const id=match.id;next.tasks=next.tasks.map(t=>t.id===id?{...item,id,updatedAt:new Date().toISOString()}:t);}else next.tasks.push({...item,updatedAt:new Date().toISOString()});count++;}save(next);$('#importer').close();showView('assignments');toast(count+' assignments imported. Review official deadlines and effort estimates.');}catch(e){$('#import-error').textContent=e.message;}};
addEventListener('hashchange',()=>showView(location.hash.slice(1)));addEventListener('online',()=>toast('Back online. GitHub sync is available.'));addEventListener('offline',()=>toast('Offline. You can keep working locally.'));addEventListener('storage',e=>{if(e.key!==KEY)return;if(confirm('Your assignments changed in another tab. Reload to see the latest saved version?'))location.reload();});
showView(location.hash.slice(1)||'assignments');if(startupError)toast(startupError);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
